-- Migration 0022 — Phase 20-21: admin identity + audit (gap register C7,
-- PHASE14-06, PHASE6-03, C18 CRM authorName).
--
-- Generated by `drizzle-kit generate` from src/schema/audit-logs.ts; this
-- header was written by hand, and the journal "when" was set to
-- 1792800000000 to keep the hand-set, strictly increasing sequence used
-- since 0012 (see 0021's header for why).
--
-- Admin requests used to be authorised by ONE shared ADMIN_API_TOKEN, so no
-- admin action could be attributed to anyone. Each administrator now has a
-- named credential (ADMIN_API_CREDENTIALS) and every admin request is
-- written to audit_logs as a platform-level row (application_id NULL,
-- user_id NULL — admins are not application users) carrying:
--   actor_type  'admin'
--   actor_id    the credential id (who)
--   action      "<METHOD> <route pattern>" or admin.auth.* (what)
--   outcome     started -> success / client_error / server_error /
--               stream_closed / aborted, or denied / locked
--   status_code the HTTP status returned
-- All additive, nullable columns: existing rows and the reconciliation
-- job's platform rows are unaffected. Every statement is a single
-- statement (production applies migrations through neon-http).

ALTER TABLE "audit_logs" ADD COLUMN "actor_type" text;--> statement-breakpoint
ALTER TABLE "audit_logs" ADD COLUMN "actor_id" text;--> statement-breakpoint
ALTER TABLE "audit_logs" ADD COLUMN "outcome" text;--> statement-breakpoint
ALTER TABLE "audit_logs" ADD COLUMN "status_code" integer;--> statement-breakpoint
CREATE INDEX "idx_audit_logs_actor" ON "audit_logs" USING btree ("actor_type","actor_id","created_at");
